// Replaces Chirpy's caching service worker. Browsers that still run the old one
// (from before offline caching was turned off) install this on their next visit:
// it takes over at once, deletes the old caches, removes itself and reloads the page.
self.addEventListener('install', () => self.skipWaiting());

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys()) await caches.delete(key);
      await self.registration.unregister();
      for (const client of await self.clients.matchAll({ type: 'window' })) client.navigate(client.url);
    })()
  );
});
